import{z as i,x as A,o as E,c as B,q as t,j as s,D as e,d as o,s as l,S as n,b as d}from"./chunks/framework.C8m1ZpeB.js";const x=JSON.parse('{"title":"数据冒险与转发","description":"","frontmatter":{"title":"数据冒险与转发","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/data-hazard-forward.md","filePath":"cs/data-hazard-forward.md","lastUpdated":1791413859000}'),p={name:"cs/data-hazard-forward.md"};function c(u,a,m,D,h,M){const r=A("Mermaid");return E(),B("div",null,[a[2]||(a[2]=t('<h1 id="数据冒险与转发" tabindex="-1">数据冒险与转发 <a class="header-anchor" href="#数据冒险与转发" aria-label="Permalink to &quot;数据冒险与转发&quot;">​</a></h1><div class="epigraph"><p>后指令要的操作数，可能还停在前指令的流水线寄存器里；从那里抄过来，不必等写回。</p><footer>—— 据 Patterson and Hennessy, Computer Organization and Design (RISC-V) 整理</footer></div><p><a href="/cs/structural-hazard">上一课</a>用分体存储和两读一写堆拿掉了结构冲突。本课不重讲端口日历。缺口是：即使硬件够用，后一条指令在 ID 读寄存器时，前一条的结果可能还在 EX 或 MEM，堆里仍是旧值。本课只处理这类数据冒险，并用转发把结果从级间寄存器送到 ALU 输入。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>add x1, x2, x3</code> 后面紧跟 <code>sub x4, x1, x5</code>。按五级时间表，<code>add</code> 在 WB 才写入 <code>x1</code>，<code>sub</code> 早两拍就在 ID 读堆。读到的是旧 <code>x1</code>，ISA 的顺序语义被打破。缺口不是再加一个 ALU，而是承认<strong>流水线里存在尚未写回的「未来寄存器值」</strong>，必须在 ALU 使用前接到正确来源。</p><p><span class="marginnote">转发就是&quot;抄近道&quot;：结果明明已经停在半路的级间寄存器里，就不等它绕回寄存器堆。类比成绩已在教务系统里，老师直接把分数抄给你，不必等成绩单寄到家。</span></p><p>load 更苛刻：数据要到 MEM 结束才出现，下一条若在 EX 就要用，转发也来不及，必须停一拍。本课把这条 load-use 停顿钉死，不把停顿推广到所有相关。</p><p><span class="marginnote">相关按读写分类：RAW 是真依赖，WAR/WAW 在五级顺序流水线里几乎不出现，因为写固定在 WB、读在 ID。乱序核里它们会回来。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>比较 EX/MEM 与 MEM/WB 流水线寄存器中的目的寄存器号，与当前 EX 级指令的源寄存器号。若匹配且前指令确实要写寄存器，把 ALU 或存储器刚得到的值 mux 进 ALU 输入，而不是用堆读出口。这就是转发（旁路）。</p><p>load 后紧跟使用：转发源在 MEM，使用者已进入 EX，路径差一拍。检测 load-use，在 ID/EX 插入气泡，让 load 先走到 MEM，下一拍再转发。</p><p><span class="marginnote">为什么恰好停一拍：<code>add</code> 的结果 EX 一结束就能转发，下一拍来得及；load 要多走完 MEM 才拿到数据，而使用者此刻已在 EX——时间表上差的就是这一拍，补一个气泡正好补齐。</span></p>',12)),(E(),s(n,null,{default:e(()=>[l(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20LR%0A%20%20EXM%5B%22EX%2FMEM%20%E7%BB%93%E6%9E%9C%22%5D%20--%3E%20MUX%5B%22ALU%20%E8%BE%93%E5%85%A5%20mux%22%5D%0A%20%20MW%5B%22MEM%2FWB%20%E7%BB%93%E6%9E%9C%22%5D%20--%3E%20MUX%0A%20%20RF%5B%22%E5%AF%84%E5%AD%98%E5%99%A8%E5%A0%86%E8%AF%BB%E5%8F%A3%22%5D%20--%3E%20MUX%0A%20%20MUX%20--%3E%20ALU%5B%22EX%20ALU%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=d("h2",{id:"机制",tabindex:"-1"},[o("机制 "),d("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=d("p",null,"转发恢复的是 ISA 看见的 RAW 顺序，不改变五级划分。编译器仍可插入无关指令填 load-use 槽，那是软件调度；硬件必须在任意指令对上正确。控制冒险尚未进场：本课假定 PC 顺序加 4。",-1)),(E(),s(n,null,{default:e(()=>[l(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22load%20x1%20%E5%90%8E%E7%B4%A7%E8%B7%9F%E7%94%A8%20x1%22%5D%20--%3E%20A%5B%22load%20%E5%9C%A8%20EX%20%E7%AE%97%E5%9C%B0%E5%9D%80%22%5D%0A%20%20A%20--%3E%20B%5B%22load%20%E5%9C%A8%20MEM%20%E6%9C%AB%E5%B0%BE%E6%89%8D%E6%8B%BF%E5%88%B0%E6%95%B0%E6%8D%AE%22%5D%0A%20%20S%20--%3E%20U%5B%22%E4%BD%BF%E7%94%A8%E8%80%85%E5%B7%B2%E5%9C%A8%20EX%20%E9%9C%80%E8%A6%81%20x1%22%5D%0A%20%20U%20--%3E%20Q%7B%22%E8%BD%AC%E5%8F%91%E6%9D%A5%E5%BE%97%E5%8F%8A%E5%90%97%22%7D%0A%20%20Q%20--%3E%7C%22%E5%B7%AE%E4%B8%80%E6%8B%8D%22%7C%20BUB%5B%22ID%2FEX%20%E6%8F%92%E5%85%A5%E4%B8%80%E4%B8%AA%E6%B0%94%E6%B3%A1%22%5D%0A%20%20BUB%20--%3E%20FWD%5B%22%E4%B8%8B%E4%B8%80%E6%8B%8D%E4%BB%8E%20MEM%2FWB%20%E8%BD%AC%E5%8F%91%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=t('<p><span class="marginnote">初学者容易以为&quot;有冒险就要加硬件&quot;。结构冒险才是端口不够；数据冒险的资源一样不缺，缺的是时间差——值还没走到该在的地方。转发不增加 ALU，只是把已存在的值提前接线。</span></p><p>检测逻辑是组合比较器加 mux 选择，延迟加在 EX 前。设计若把时钟再压紧，转发路径会成为新的关键路径；那是实现约束，不是语义缺口。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不处理分支用到的条件与目标——它们在 EX 才齐，属于<a href="/cs/control-hazard-predict">控制冒险与分支预测</a>。也不引入寄存器重命名：五级里 WAR/WAW 被固定写回点挡住。浮点多周期运算的相关，后课 Tomasulo 才系统处理。</p><p>后课默认：整数 ALU 相关用转发消除；load-use 仍可能停一拍。谈到「数据冒险」，先指 RAW。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>数据冒险是后指令要用的值还在流水线里，堆尚未更新。</li><li>转发从 EX/MEM、MEM/WB 旁路到 ALU；load-use 仍要一拍气泡。</li><li>控制相关是后课的缺口。</li><li>出处：Patterson and Hennessy, <em>COD</em> RISC-V 数据冒险与转发。</li></ul>',7))])}const _=i(p,[["render",c]]);export{x as __pageData,_ as default};
